import mongoose from "mongoose";
import { AIChat, Topic, Mistake, Profile } from "../models/index.js";
import * as ai from "./ai/index.js";

/**
 * Mentor service — the AI Mentor dock (API_SPEC.md → global `AiChatDock`).
 * Replies are generated by the AI provider (see services/ai/), grounded in the
 * student's weakest topic, pending-mistake count and accuracy. With no API key
 * configured, the AI facade returns a data-grounded fallback (never a dummy).
 */

/** Resolve the target conversation: by id, else the latest, else null. */
async function resolveChat(userId, conversationId) {
  if (conversationId && mongoose.isValidObjectId(conversationId)) {
    const byId = await AIChat.findOne({ _id: conversationId, user: userId });
    if (byId) return byId;
  }
  return AIChat.findOne({ user: userId }).sort({ updatedAt: -1 });
}

/** GET /mentor/messages?conversationId= */
export async function getMessages(userId, conversationId) {
  const chat = await resolveChat(userId, conversationId);
  if (!chat) return { conversationId: null, data: [] };
  return {
    conversationId: String(chat._id),
    data: chat.messages.map((m) => ({ role: m.role, text: m.text })),
  };
}

/** Gather the grounding context for a mentor reply. */
async function buildContext(userId, question) {
  const [weakest, pendingMistakes, profile] = await Promise.all([
    Topic.findOne({ user: userId }).sort({ mastery: 1 }),
    Mistake.countDocuments({ user: userId, status: "Pending" }),
    Profile.findOne({ user: userId }),
  ]);
  return {
    question,
    weakest: weakest ? { name: weakest.name, mastery: weakest.mastery } : null,
    pendingMistakes,
    accuracy: profile?.accuracy,
    groundingRefs: [
      weakest ? `topic:${weakest.key}` : null,
      pendingMistakes ? `mistakes:pending:${pendingMistakes}` : null,
    ].filter(Boolean),
  };
}

/** POST /mentor/chat { conversationId, text } → append user + ai turns, return the reply. */
export async function chat(userId, { conversationId, text }) {
  let chatDoc = await resolveChat(userId, conversationId);
  if (!chatDoc) {
    chatDoc = await AIChat.create({ user: userId, title: "Mentor chat", messages: [] });
  }

  const ctx = await buildContext(userId, text);
  const { text: replyText } = await ai.mentorReply(ctx);

  chatDoc.messages.push({ role: "user", text });
  chatDoc.messages.push({ role: "ai", text: replyText, groundingRefs: ctx.groundingRefs });
  await chatDoc.save();

  return {
    conversationId: String(chatDoc._id),
    reply: { role: "ai", text: replyText, groundingRefs: ctx.groundingRefs },
  };
}

export default { getMessages, chat };
